2	
3	import (
4		"errors"
5		"testing"
6		"time"
7	)
8	
9	// “同一旧版先被较晚版本截短、随后在剩余有效期内又被更早版本截短”
10	// 场景的固定时间线（全部为 UTC 零点，结束时刻不含）：
11	//
12	//	旧版 seat-v1：单价 150 分，2026-03-01 起，登记结束 2026-03-31
13	//	较晚版本 seat-v3：单价 200 分，2026-03-20 起替代 v1，持续有效
14	//	更早版本 seat-v2：单价 180 分，拟从 2026-03-10 起替代 v1，结束 2026-03-20
15	//
16	// 登记顺序是 v1、v3、v2，而不是按生效日期排列。v3 登记后 v1 的实际结束
17	// 已提前到 3 月 20 日，但 v2 的交接点 3 月 10 日仍落在 v1 当前的实际有效
18	// 区间 [03-01, 03-20) 内：不能因为 v1 已显示被 v3 替代就拒绝这次登记，
19	// 也不能让 v2 占用已安排好的 v3 的有效时间。所有时刻写死并注入固定时钟，
20	// 结论不依赖运行当天的真实日期或时间流逝。
21	var (
22		dtOldStart     = time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC)
23		dtOldEnd       = time.Date(2026, 3, 31, 0, 0, 0, 0, time.UTC)
24		dtEarlyHandoff = time.Date(2026, 3, 10, 0, 0, 0, 0, time.UTC)
25		dtLateHandoff  = time.Date(2026, 3, 20, 0, 0, 0, 0, time.UTC)
26	)
27	
28	// newTwiceTruncatedBaseBook 准备按 v1、v3 顺序登记了两个版本的账本：
29	// v3 从 3 月 20 日起替代 v1，v1 的实际结束已被截短到 3 月 20 日，
30	// 登记结束仍是 3 月 31 日。
31	func newTwiceTruncatedBaseBook(t *testing.T) *Book {
32		t.Helper()
33		now, _ := fixedClock(dtOldStart)
34		b := NewBook(WithClock(now))
35		oldEnd := dtOldEnd
36		if err := b.RegisterVersion(RegisterRequest{
37			ItemID: "seat", VersionID: "seat-v1", UnitPrice: 150,
38			Start: dtOldStart, End: &oldEnd,
39		}); err != nil {
40			t.Fatalf("register seat-v1: %v", err)
41		}
42		if err := b.RegisterVersion(RegisterRequest{
43			ItemID: "seat", VersionID: "seat-v3", UnitPrice: 200,
44			Start: dtLateHandoff, Replaces: "seat-v1",
45		}); err != nil {
46			t.Fatalf("register seat-v3: %v", err)
47		}
48		return b
49	}
50	
51	// assertTwiceTruncatedBaseUnchanged 校验失败的 v2 登记整次回滚：
52	// 查询仍只有 v1、v3；v1 保持被 v3 截短后的状态（登记结束 3 月 31 日、
53	// 实际结束 3 月 20 日、由 v3 替代），v3 的信息不变，
54	// 失败的 v2 及其版本标识都不留痕迹。
55	func assertTwiceTruncatedBaseUnchanged(t *testing.T, b *Book) {
56		t.Helper()
57		views, err := b.ItemVersions("seat")
58		if err != nil {
59			t.Fatal(err)
60		}
61		if len(views) != 2 {
62			t.Fatalf("失败登记后应仍只有两个版本，got %d: %+v", len(views), views)
63		}
64		old, late := views[0], views[1]
65		if old.VersionID != "seat-v1" || late.VersionID != "seat-v3" {
66			t.Fatalf("失败登记后版本集合/顺序异常: %q, %q", old.VersionID, late.VersionID)
67		}
68	
69		// 旧版：登记结束仍是 3 月 31 日，实际结束保持被 v3 截短后的 3 月 20 日，
70		// 不能被失败登记再提前到 3 月 10 日，替代关系也不能改写。
71		if old.UnitPrice != 150 {
72			t.Fatalf("旧版单价被改写: %d", old.UnitPrice)
73		}
74		if old.End == nil || !old.End.Equal(dtOldEnd) {
75			t.Fatalf("旧版登记结束被改写: %v", old.End)
76		}
77		if old.EffectiveEnd == nil || !old.EffectiveEnd.Equal(dtLateHandoff) {
78			t.Fatalf("旧版实际结束应保持被 v3 截短后的 3 月 20 日, got %v", old.EffectiveEnd)
79		}
80		if old.Replaces != "" || old.SupersededBy != "seat-v3" {
81			t.Fatalf("旧版替代关系被失败登记改写: Replaces=%q SupersededBy=%q",
82				old.Replaces, old.SupersededBy)
83		}
84	
85		// 较晚版本：从 3 月 20 日起持续有效，替代来源仍是 v1。
86		if late.UnitPrice != 200 || !late.Start.Equal(dtLateHandoff) {
87			t.Fatalf("较晚版本登记信息被改写: %+v", late)
88		}
89		if late.End != nil || late.EffectiveEnd != nil {
90			t.Fatalf("较晚版本应仍持续有效: 登记结束=%v 实际结束=%v",
91				late.End, late.EffectiveEnd)
92		}
93		if late.Replaces != "seat-v1" || late.SupersededBy != "" {
94			t.Fatalf("较晚版本替代关系被改写: Replaces=%q SupersededBy=%q",
95				late.Replaces, late.SupersededBy)
96		}
97	}
98	
99	// 旧版虽已被 v3 截短，v2 的登记仍不能挤占 v3 已经安排好的有效时间：
100	// 不填结束时间会延伸进持续有效的 v3；结束时间只要晚于 3 月 20 日零点，
101	// 哪怕只超出一纳秒，都必须返回现有的 ErrOverlap。
102	func TestSecondTruncationOverlappingSuccessorRejected(t *testing.T) {
103		cases := []struct {
104			name string
105			end  *time.Time
106		}{
107			{"不填结束时间-持续有效", nil},
108			{"结束晚于较晚版本开始一纳秒", timePtr(dtLateHandoff.Add(time.Nanosecond))},
109			{"结束晚于较晚版本开始一分钟", timePtr(dtLateHandoff.Add(time.Minute))},
110			{"结束晚于较晚版本开始一整天", timePtr(dtLateHandoff.Add(24 * time.Hour))},
111		}
112		for _, c := range cases {
113			t.Run(c.name, func(t *testing.T) {
114				b := newTwiceTruncatedBaseBook(t)
115	
116				err := b.RegisterVersion(RegisterRequest{
117					ItemID: "seat", VersionID: "seat-v2", UnitPrice: 180,
118					Start: dtEarlyHandoff, End: c.end, Replaces: "seat-v1",
119				})
120				if !errors.Is(err, ErrOverlap) {
121					t.Fatalf("挤占较晚版本有效时间的登记应返回 ErrOverlap, got %v", err)
122				}
123	
124				// 失败不留痕迹：v1 保持被 v3 截短后的状态，v3 不变，v2 不存在。
125				assertTwiceTruncatedBaseUnchanged(t, b)
126			})
127		}
128	}
129	
130	// 完整回归：v2 先因挤占 v3 被拒，修正结束时间为 3 月 20 日后沿用同一
131	// 版本标识登记成功——失败不占用版本标识。v1 虽已被 v3 替代，但 3 月 10 日
132	// 仍落在它当前的实际有效区间内，登记必须被接受，不能误报替代来源无效；
133	// v2 与 v3 只是端点相接（结束时刻不含），不能误判重叠。
134	// 成功后三个版本的登记边界、实际有效区间与替代关系逐一符合预期，
135	// 尤其 v3 原登记的替代来源 v1 不能为了排列成连续链而改写成 v2。
136	func TestSecondTruncationRejectedThenSucceedsWithSameVersionID(t *testing.T) {
137		b := newTwiceTruncatedBaseBook(t)
138	
139		// 第一次尝试：不填结束时间，延伸进 v3 的有效时间，被拒。
140		err := b.RegisterVersion(RegisterRequest{
141			ItemID: "seat", VersionID: "seat-v2", UnitPrice: 180,
142			Start: dtEarlyHandoff, Replaces: "seat-v1",
143		})
144		if !errors.Is(err, ErrOverlap) {
145			t.Fatalf("无结束时间的登记应返回 ErrOverlap, got %v", err)
146		}
147		assertTwiceTruncatedBaseUnchanged(t, b)
148	
149		// 修正结束时间为 3 月 20 日零点（不含），沿用原标识与其余登记内容。
150		fixedEnd := dtLateHandoff
151		if err := b.RegisterVersion(RegisterRequest{
152			ItemID: "seat", VersionID: "seat-v2", UnitPrice: 180,
153			Start: dtEarlyHandoff, End: &fixedEnd, Replaces: "seat-v1",
154		}); err != nil {
155			t.Fatalf("失败登记不应占用版本标识，修正后沿用原标识应成功, got %v", err)
156		}
157	
158		views, err := b.ItemVersions("seat")
159		if err != nil {
160			t.Fatal(err)
161		}
162		if len(views) != 3 {
163			t.Fatalf("成功后应有三个版本, got %d: %+v", len(views), views)
164		}
165		old, early, late := views[0], views[1], views[2]
166		if old.VersionID != "seat-v1" || early.VersionID != "seat-v2" ||
167			late.VersionID != "seat-v3" {
168			t.Fatalf("版本应按生效时刻排列为 v1/v2/v3: %q, %q, %q",
169				old.VersionID, early.VersionID, late.VersionID)
170		}
171	
172		// 旧版：登记结束仍是 3 月 31 日（永不因后续登记改变），
173		// 实际结束被 v2 进一步提前到 3 月 10 日，改显示由 v2 替代。
174		if old.UnitPrice != 150 || !old.Start.Equal(dtOldStart) {
175			t.Fatalf("旧版登记信息异常: %+v", old)
176		}
177		if old.End == nil || !old.End.Equal(dtOldEnd) {
178			t.Fatalf("旧版登记结束应仍为 3 月 31 日, got %v", old.End)
179		}
180		if old.EffectiveEnd == nil || !old.EffectiveEnd.Equal(dtEarlyHandoff) {
181			t.Fatalf("旧版实际结束应被 v2 提前到 3 月 10 日, got %v", old.EffectiveEnd)
182		}
183		if old.Replaces != "" || old.SupersededBy != "seat-v2" {
184			t.Fatalf("旧版替代关系异常: Replaces=%q SupersededBy=%q",
185				old.Replaces, old.SupersededBy)
186		}
187	
188		// 更早版本：实际有效区间为 [3 月 10 日, 3 月 20 日)，替代 v1。
189		if early.UnitPrice != 180 {
190			t.Fatalf("更早版本单价应为 180, got %d", early.UnitPrice)
191		}
192		if !early.Start.Equal(dtEarlyHandoff) || !early.EffectiveStart.Equal(dtEarlyHandoff) {
193			t.Fatalf("更早版本开始时刻应为 3 月 10 日: %+v", early)
194		}
195		if early.End == nil || !early.End.Equal(dtLateHandoff) ||
196			early.EffectiveEnd == nil || !early.EffectiveEnd.Equal(dtLateHandoff) {
197			t.Fatalf("更早版本有效区间应为 [03-10, 03-20): 登记结束=%v 实际结束=%v",
198				early.End, early.EffectiveEnd)
199		}
200		if early.Replaces != "seat-v1" || early.SupersededBy != "" {
201			t.Fatalf("更早版本替代关系异常: Replaces=%q SupersededBy=%q",
202				early.Replaces, early.SupersededBy)
203		}
204	
205		// 较晚版本：起止时间不变，原登记的替代来源 v1 保持原值，
206		// 不能为了把替代关系排列成 v1→v2→v3 连续链而改写成 v2。
207		if late.UnitPrice != 200 || !late.Start.Equal(dtLateHandoff) {
208			t.Fatalf("较晚版本登记信息异常: %+v", late)
209		}
210		if late.End != nil || late.EffectiveEnd != nil {
211			t.Fatalf("较晚版本应仍持续有效: 登记结束=%v 实际结束=%v",
212				late.End, late.EffectiveEnd)
213		}
214		if late.Replaces != "seat-v1" || late.SupersededBy != "" {
215			t.Fatalf("较晚版本替代来源应保持 v1 不变: Replaces=%q SupersededBy=%q",
216				late.Replaces, late.SupersededBy)
217		}
218	}
219	
220	// 二次截短后按指定时刻查询：选择依据是各版本的实际有效区间，
221	// 不能沿用登记顺序（v1、v3、v2），也不能沿用 v1 的月底登记结束日期。
222	// [03-01, 03-10) 选 v1，3 月 10 日交接点（含）至 3 月 20 日前选 v2，
223	// 3 月 20 日交接点（含）起选 v3；查询返回的单价与版本列表一致。
224	func TestEffectiveVersionAtAfterSecondTruncation(t *testing.T) {
225		now, _ := fixedClock(dtOldStart)
226		b := NewBook(WithClock(now))
227		oldEnd := dtOldEnd
228		earlyEnd := dtLateHandoff
229		for _, req := range []RegisterRequest{
230			{ItemID: "seat", VersionID: "seat-v1", UnitPrice: 150, Start: dtOldStart, End: &oldEnd},
231			{ItemID: "seat", VersionID: "seat-v3", UnitPrice: 200, Start: dtLateHandoff, Replaces: "seat-v1"},
232			{ItemID: "seat", VersionID: "seat-v2", UnitPrice: 180, Start: dtEarlyHandoff, End: &earlyEnd, Replaces: "seat-v1"},
233		} {
234			if err := b.RegisterVersion(req); err != nil {
235				t.Fatalf("register %s: %v", req.VersionID, err)
236			}
237		}
238	
239		cases := []struct {
240			name      string
241			at        time.Time
242			versionID string
243			unitPrice int64
244		}{
245			{"v1 生效起点-含", dtOldStart, "seat-v1", 150},
246			{"v2 交接点前一纳秒", dtEarlyHandoff.Add(-time.Nanosecond), "seat-v1", 150},
247			{"v2 交接点-含", dtEarlyHandoff, "seat-v2", 180},
248			{"v2 区间中段", time.Date(2026, 3, 15, 12, 0, 0, 0, time.UTC), "seat-v2", 180},
249			{"v3 交接点前一纳秒", dtLateHandoff.Add(-time.Nanosecond), "seat-v2", 180},
250			{"v3 交接点-含", dtLateHandoff, "seat-v3", 200},
251			{"v1 登记结束当天仍选 v3", dtOldEnd, "seat-v3", 200},
252			{"v1 登记结束之后仍选 v3", dtOldEnd.Add(24 * time.Hour), "seat-v3", 200},
253		}
254		for _, c := range cases {
255			t.Run(c.name, func(t *testing.T) {
256				view, err := b.EffectiveVersionAt("seat", c.at)
257				if err != nil {
258					t.Fatalf("查询应命中版本: %v", err)
259				}
260				if view.VersionID != c.versionID || view.UnitPrice != c.unitPrice {
261					t.Fatalf("时刻 %v 应选 %s（%d 分）, got %s（%d 分）",
262						c.at, c.versionID, c.unitPrice, view.VersionID, view.UnitPrice)
263				}
264			})
265		}
266	
267		// 首版开始之前没有任何生效版本，不拿邻近的 v1 补位。
268		if _, err := b.EffectiveVersionAt("seat", dtOldStart.Add(-time.Nanosecond)); !errors.Is(err, ErrNoEffectiveVersion) {
269			t.Fatalf("首版开始之前应返回 ErrNoEffectiveVersion, got %v", err)
270		}
271	}
272	
273	// 报价与查询共用同一套实际有效期判断：时钟停在 v2 的有效区间内时，
274	// 引用 v2 按 180 分确认，引用实际结束已提前到 3 月 10 日的 v1 则以
275	// version_expired 拒绝——即使 v1 的登记结束 3 月 31 日仍在将来。
276	func TestQuoteAfterSecondTruncation(t *testing.T) {
277		now, setNow := fixedClock(dtOldStart)
278		b := NewBook(WithClock(now))
279		oldEnd := dtOldEnd
280		earlyEnd := dtLateHandoff
281		for _, req := range []RegisterRequest{
282			{ItemID: "seat", VersionID: "seat-v1", UnitPrice: 150, Start: dtOldStart, End: &oldEnd},
283			{ItemID: "seat", VersionID: "seat-v3", UnitPrice: 200, Start: dtLateHandoff, Replaces: "seat-v1"},
284			{ItemID: "seat", VersionID: "seat-v2", UnitPrice: 180, Start: dtEarlyHandoff, End: &earlyEnd, Replaces: "seat-v1"},
285		} {
286			if err := b.RegisterVersion(req); err != nil {
287				t.Fatalf("register %s: %v", req.VersionID, err)
288			}
289		}
290	
291		acceptedAt := time.Date(2026, 3, 15, 10, 0, 0, 0, time.UTC)
292		setNow(acceptedAt)
293	
294		fresh, err := b.Quote(QuoteRequest{
295			RequestID: "dt-v2-360", ItemID: "seat", VersionID: "seat-v2", Quantity: 2,
296		})
297		if err != nil {
298			t.Fatalf("引用 v2 是正常受理，err 应为空: %v", err)
299		}
300		if !fresh.Confirmed || fresh.UnitPrice != 180 || fresh.Total != 360 {
301			t.Fatalf("v2 报价应按 180 分确认 360 分: %+v", fresh)
302		}
303		if !fresh.AcceptedAt.Equal(acceptedAt) || fresh.Reason != ReasonNone {
304			t.Fatalf("v2 确认结果受理时刻/拒绝原因异常: %+v", fresh)
305		}
306	
307		expired, err := b.Quote(QuoteRequest{
308			RequestID: "dt-v1-expired", ItemID: "seat", VersionID: "seat-v1", Quantity: 2,
309		})
310		if err != nil {
311			t.Fatalf("引用 v1 是正常受理，err 应为空: %v", err)
312		}
313		if expired.Confirmed || expired.Reason != ReasonVersionExpired {
314			t.Fatalf("v1 实际结束已提前到受理时刻之前，应以 version_expired 拒绝: %+v", expired)
315		}
316		if expired.UnitPrice != 0 || expired.Total != 0 {
317			t.Fatalf("拒绝结果单价/总价应为零: 单价=%d 总价=%d", expired.UnitPrice, expired.Total)
318		}
319	}
